INSERT INTO TbUsuariosHistoricosLocal ( EmpresaUsuario, EmpresaTramitadora, JuridicaContrato, CodExp, ID, DNI, Nombre, Apellido_1, Apellido_2, Telefono, Correo_e, IDExpediente, F_Nacimiento, LugarNacimiento, Motivo_HPS, F_Curso, CursoEnVigor, Requiere_Curso, FechaPrimeraConvocatoria, FechaSegundaConvocatoria, FechaCorreoNoCurso, F_Baja, LugarPrestacionServicio )
SELECT S1.Nombre AS EmpresaUsuario, S2.Nombre AS EmpresaTramitadora, H.CadenaContratistas AS JuridicaContrato, E.CodExp, H.ID, H.DNI, H.Nombre, H.Apellido_1, H.Apellido_2, H.Telefono, H.Correo_e, H.IDExpediente, H.F_Nacimiento, H.LugarNacimiento, H.Motivo_HPS, H.F_Curso, H.CursoEnVigor, H.Requiere_Curso, H.FechaPrimeraConvocatoria, H.FechaSegundaConvocatoria, H.FechaCorreoNoCurso, H.F_Baja, H.LugarPrestacionServicio
FROM ((TbUsuariosHistoricos AS H LEFT JOIN TbSuministradores AS S1 ON H.IDEmpresaUsuario = S1.IDSuministrador) LEFT JOIN TbSuministradores AS S2 ON H.IDEmpresaHPS = S2.IDSuministrador) LEFT JOIN TbExpedientes AS E ON H.IDExpediente = E.IDExpediente;
